		errors.As(err, &cause)
		return &MembersRefusedError{Group: repoName, Status: status, Anonymous: !hasAuth, Cause: cause}
	}
	var se *oci.StatusError
	if !errors.As(err, &se) || se.Source != oci.SourceManagementAPI {
